import sys

data = sys.stdin.read().split()
pos = 0

def read_tree():
    global pos
    n = int(data[pos])
    pos += 1
    keys, vals, par = [], [], []
    for _ in range(n):
        keys.append(data[pos])
        vals.append(int(data[pos + 1]))
        par.append(int(data[pos + 2]))
        pos += 3
    return keys, vals, par

def paths(keys, par):
    res = []
    for i in range(len(keys)):
        if par[i] < 0:
            res.append(('',))
        else:
            res.append(res[par[i]] + (keys[i],))
    return res

sk, sv, sp = read_tree()
tk, tv, tp = read_tree()
total = {}
for tr in ((sk, sv, sp), (tk, tv, tp)):
    for path, v in zip(paths(tr[0], tr[2]), tr[1]):
        total[path] = total.get(path, 0) + v
lines = []
for path in sorted(total):
    key = path[-1] if len(path) > 1 else tk[0]
    lines.append('%d %s %d' % (len(path) - 1, key, total[path]))
print('\n'.join(lines))

